function rnd(a, b) { return a + Math.random() * (b - a); }

/* ---------- Audio (Web Audio API) ---------- */
var AC = null;
function audio() {
  if (!AC) { try { AC = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { AC = null; } }
  if (AC && AC.state === 'suspended') AC.resume();
  return AC;
}
function tone(f, d, type, vol, slide, delay) {
  if (S.muted) return; var a = audio(); if (!a) return;
  var t = a.currentTime + (delay || 0), o = a.createOscillator(), g = a.createGain();
  o.type = type || 'square'; o.frequency.setValueAtTime(f, t);
  if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, slide), t + d);
  g.gain.setValueAtTime(vol || 0.12, t); g.gain.exponentialRampToValueAtTime(0.0001, t + d);
  o.connect(g); g.connect(a.destination); o.start(t); o.stop(t + d + 0.02);
}
var SFX = {
  click: function () { tone(660, 0.07, 'square', 0.1); },
  select: function () { tone(523, 0.08, 'triangle', 0.15); tone(784, 0.1, 'triangle', 0.15, 0, 0.07); },
  start: function () { [392, 523, 659, 784].forEach(function (f, i) { tone(f, 0.12, 'square', 0.1, 0, i * 0.09); }); },
  flap: function () { tone(380, 0.12, 'sine', 0.16, 720); },
  jump: function () { tone(250, 0.18, 'square', 0.09, 560); },
  score: function () { tone(988, 0.07, 'square', 0.09); tone(1319, 0.12, 'square', 0.09, 0, 0.07); },
  hit: function () { tone(180, 0.3, 'sawtooth', 0.2, 40); },
  kick: function () { tone(150, 0.12, 'sine', 0.25, 60); },
  win: function () { [523, 659, 784, 1047, 1319].forEach(function (f, i) { tone(f, 0.18, 'square', 0.1, 0, i * 0.1); }); }
};
var overEl = null;
function playGameOver() {
  if (S.muted || !GAMEOVER_AUDIO) return;
  try {
    var src = GAMEOVER_AUDIO.indexOf('data:') === 0 ? GAMEOVER_AUDIO : 'data:audio/mpeg;base64,' + GAMEOVER_AUDIO;
    if (!overEl) overEl = new Audio(src);
    overEl.pause(); overEl.currentTime = 0;
    var p = overEl.play(); if (p && p.catch) p.catch(function () {});
  } catch (e) {}
}
function stopGameOver() { if (overEl) { try { overEl.pause(); overEl.currentTime = 0; } catch (e) {} } }
function paintMute() { $('muteBtn').textContent = S.muted ? '🔇' : '🔊'; }
